    "title": "⚡ [AUTO APPROVED] " + (($('Receive Proposal Webhook').first().json.body?.action || 'ACTION').toUpperCase()) + " " + ($('Receive Proposal Webhook').first().json.body?.target || ''),
    "priority": 3,
    "tags": ["white_check_mark", "robot"],
    "message": "✅ SAFE TASK AUTO-EXECUTED\n\nReason: " + ($('Receive Proposal Webhook').first().json.body?.reason || 'Automated recovery')
  }
}}

={{
  {
    "topic": "homelab-approve",
    "title": (($('Receive Proposal Webhook').first().json.body?.action || 'ACTION').toUpperCase()) + " " + ($('Receive Proposal Webhook').first().json.body?.target || ''),
    "priority": 4,
    "tags": ["warning", "robot"],
    "message": $('Receive Proposal Webhook').first().json.body?.reason || 'Recovery task approval required',
    "actions": [
      {
        "action": "http",
        "label": "APPROVE",
        "url": $env["N8N_PUBLIC_DOMAIN"] + "/webhook/tlab-decision?execution_id=" + $execution.id + "&action=" + ($('Receive Proposal Webhook').first().json.body?.action || '') + "&target=" + encodeURIComponent($('Receive Proposal Webhook').first().json.body?.target || '') + "&asset_type=" + ($('Receive Proposal Webhook').first().json.body?.asset_type || '') + "&vmid=" + ($('Receive Proposal Webhook').first().json.body?.vmid || '') + "&node_ip=" + ($('Receive Proposal Webhook').first().json.body?.node_ip || '') + "&node_name=" + ($('Receive Proposal Webhook').first().json.body?.node_name || '') + "&pve_token=" + encodeURIComponent($('Receive Proposal Webhook').first().json.body?.pve_token || '') + "&decision=approve",
        "method": "GET",
        "clear": true
      },
      {
        "action": "http",
        "label": "REJECT",
        "url": $env["N8N_PUBLIC_DOMAIN"] + "/webhook/tlab-decision?execution_id=" + $execution.id + "&action=" + ($('Receive Proposal Webhook').first().json.body?.action || '') + "&target=" + encodeURIComponent($('Receive Proposal Webhook').first().json.body?.target || '') + "&decision=reject",
        "method": "GET",
        "clear": true
      }
    ]
  }
}}

={{
